    const ds=this.add.text(x+52,y+h*(compact?0.70:0.69),safeSub,{fontFamily:'sans-serif',fontSize:compact?'9px':'10.5px',color:'#b7abc9',wordWrap:{width:textW}}).setOrigin(0,0.5);
