    if(c.moveIn<=0){const p=this.objectivePosition(0,1,210,420);c.tx=p.x;c.ty=p.y;c.moveIn=5.2;}
    const dx=c.tx-c.x,dy=c.ty-c.y,d=Math.hypot(dx,dy),step=Math.min(d,46*dt);if(d>1){c.x+=dx/d*step;c.y+=dy/d*step;}
