    if(this.stageIndex!==9||!['wave','mini','boss'].includes(this.mode))return;if(!this._rootThrone)this._rootThrone={t:4.5,pulse:0};const r=this._rootThrone;r.t-=dt;if(r.t>0)return;r.pulse++;r.t=this.mode==='boss'?7.8:10.5;
