      for(let i=0;i<n;i++)this.time.delayedCall(i*48,()=>{ if(!live())return; const f=pt(0.5+Math.random()*0.15,(Math.random()-0.5)*26); streak(f,0xffe2b8,5); hit(f.x,f.y,reach*0.45,0.32); if(i%2)this._sqX=1.12; });
