        const g=this.camWorld(this.add.graphics().setDepth(8)); g.lineStyle(12,0xfff0b0,0.95).lineBetween(f.x,f.y+30,f.x,f.y-70); this.tweens.add({targets:g,alpha:0,y:-20,duration:200,onComplete:()=>g.destroy()});
